**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <set>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    string klucz;
    plik >> klucz;

    cout << "Klucz: " << klucz << endl;
    cout << endl << "a) Szyfrowanie Vigenere'a:" << endl;

    string s;
    vector<string> szyfrogramy;
    while (plik >> s) {
        string wynik = "";
        for (int i = 0; i < (int)s.length(); i++) {
            int shift = klucz[i % klucz.length()] - 'a';
            char c = (s[i] - 'a' + shift) % 26 + 'a';
            wynik += c;
        }
        cout << s << " -> " << wynik << endl;
        szyfrogramy.push_back(wynik);
    }

    cout << endl << "b) Unikalne litery w szyfrogramie:" << endl;
    int ile = 0;
    for (const string& sz : szyfrogramy) {
        set<char> unik(sz.begin(), sz.end());
        cout << sz << ": " << unik.size() << " roznych liter" << endl;
        if ((int)unik.size() >= 5) ile++;
    }
    cout << "Szyfrogramy z >= 5 roznymi literami: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Vigenere = Cezar ze zmiennym przesunieciem. Klucz powtarza sie cyklicznie dzieki `i % dlKlucza`. Modulo 26 zawijaka alfabet.

Weryfikacja szyfrowania (klucz: k=10,l=11,u=20,c=2,z=25):
- atak: a(0)+10=k, t(19)+11=e(4), a(0)+20=u, k(10)+2=m -> keum
- obrona: o+k=y, b+l=m, r+u=l, o+c=q, n+z=m, a+k=k -> ymlqmk
- szyfr: s+k=c, z+l=k, y+u=s, f+c=h, r+z=q -> ckshq
- haslo: h+k=r, a+l=l, s+u=m, l+c=n, o+z=n -> rlmnn
- programowanie: p+k=z, r+l=c, o+u=i, g+c=i, r+z=q, a+k=k, m+l=x, o+u=i, w+c=y, a+z=z, n+k=x, i+l=t, e+u=y -> zciiqkxiyzxty

Unikalne litery: keum(4), ymlqmk(5:{y,m,l,q,k}), ckshq(5:{c,k,s,h,q}), rlmnn(4:{r,l,m,n}), zciiqkxiyzxty(8:{z,c,i,q,k,x,y,t})
Z >= 5: ymlqmk, ckshq, zciiqkxiyzxty = 3
